// Illustrative: the store's point is an archive that outlives the streams and answers questions after they end, which one marble run cannot show.
// the copy channel: it keeps nothing, so a copy sent while the store is not listening is lost
copies$ = new Subject<Copy>();

handed$ = evidence$.pipe(
  // the fire-and-forget copy: only the envelope
  tap((evidence) => copies$.next(envelopeOf(evidence))),
);
filed$ = report$.pipe(
  // the fire-and-forget copy: the whole report
  tap((report) => copies$.next(report)),
);

entries$ = copies$.pipe(
  // next would run the store at once; this moves its work after the hand-over
  observeOn(asapScheduler),
  // the message store: append each copy that arrives
  scan((entries, copy) => [...entries, copy], [] as readonly Copy[]),
  // the store's entries, kept for whoever asks later
  shareReplay(1),
);

answer$ = entries$.pipe(
  // the query: answered from the store alone, never from handed$ or filed$
  map((entries) => entriesFor(order, entries)),
);
